{
  "apiVersion": 1,
  "type": "component.batch",
  "data": {
    "count": 3,
    "results": [
      {
        "selector": "AvatarGroup",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "AvatarGroup",
            "displayName": "Avatar Group",
            "group": "Avatar",
            "category": "Content",
            "keywords": [
              "avatar",
              "group",
              "facepile",
              "stack",
              "overlap",
              "participants",
              "assignees",
              "members",
              "team"
            ],
            "usage": {
              "description": "AvatarGroup displays multiple avatars in an overlapping row with an optional overflow indicator. Uses a compositional API: pass Avatar children directly so each avatar can carry its own props (status dots, click handlers, etc.).",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Slice the list yourself and pass only the avatars you want visible; 3-5 is typical. The group renders exactly the children it is given and never slices for you."
                },
                {
                  "guidance": true,
                  "description": "Use AvatarGroupOverflow for custom overflow content like a popover trigger or \"add member\" button."
                },
                {
                  "guidance": true,
                  "description": "Pass status dots, click handlers, or tooltips directly on each Avatar child."
                },
                {
                  "guidance": true,
                  "description": "Wrap an Avatar child in HoverCard or Tooltip to show more on hover; the avatars still overlap. Set tooltip={false} on the wrapped Avatar so its built-in name tooltip does not compete."
                },
                {
                  "guidance": true,
                  "description": "Make avatars interactive with href or onClick to link to profiles. Interactive avatars share a single Tab stop; arrow keys move between them, and the group announces a keyboard hint to assistive tech. This follows the WAI-ARIA APG roving tabindex technique for managing focus in a composite: https://www.w3.org/WAI/ARIA/apg/practices/keyboard-interface/#kbd_roving_tabindex"
                },
                {
                  "guidance": false,
                  "description": "Don't nest AvatarGroups; use a single group with all avatars."
                },
                {
                  "guidance": false,
                  "description": "Don't set size on the child avatars. The group's size wins over each child's own size prop, including when the group leaves size at its default, so a child's size is silently ignored inside a group."
                }
              ],
              "anatomy": [
                {
                  "name": "Avatar children",
                  "required": true,
                  "description": "Avatar elements that form the overlapping row. Each can have its own props."
                },
                {
                  "name": "Overflow indicator",
                  "required": false,
                  "description": "A \"+N\" circle at the end showing hidden count, or a custom AvatarGroupOverflow slot."
                }
              ]
            },
            "theming": {
              "targets": [
                {
                  "className": "astryx-avatar-group",
                  "visualProps": [
                    "size",
                    "shape"
                  ]
                },
                {
                  "className": "astryx-avatar-group-overflow",
                  "visualProps": [
                    "size",
                    "shape"
                  ]
                }
              ]
            },
            "description": "Stacked avatar display with overlapping layout and optional overflow indicator. Children are Avatar elements.",
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Avatar children, optionally followed by one AvatarGroupOverflow. Consumers handle slicing to the desired visible count.",
                "required": true,
                "slotElements": [
                  {
                    "__element": "Avatar",
                    "props": {
                      "name": "User"
                    }
                  }
                ]
              },
              {
                "name": "size",
                "type": "'xsm' | 'sm' | 'md' | 'lg' | 'xl' | 16 | 20 | 24 | 32 | 36 | 40 | 48 | 60 | 64 | 72 | 96 | 128 | 144 | 180",
                "description": "Size applied to all avatars: named sizes are 'xsm' (20px), 'sm' (24px), 'md' (36px), 'lg' (48px), and 'xl' (128px); numeric sizes must be one of the pixel values listed in the type. The group's size always overrides each child Avatar's size, including when the group uses its default size.",
                "default": "'md'"
              },
              {
                "name": "shape",
                "type": "'circle' | 'rounded' | 'square'",
                "description": "Shape applied to all avatars via context, overriding each avatar's own shape prop. Also applied to AvatarGroupOverflow's \"+N\" indicator.",
                "default": "'circle'"
              },
              {
                "name": "ref",
                "type": "React.Ref<HTMLDivElement>",
                "description": "Ref forwarded to the root element."
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "StyleX styles for layout customization."
              },
              {
                "name": "data-testid",
                "type": "string",
                "description": "Test selector for automated testing frameworks."
              }
            ],
            "components": [
              {
                "name": "AvatarGroupOverflow"
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/AvatarGroup",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "AvatarGroupOverflow",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "AvatarGroupOverflow",
            "subComponentOf": "AvatarGroup",
            "displayName": "Avatar Group Overflow",
            "isHiddenFromOverview": true,
            "description": "Overflow indicator for AvatarGroup. Shows a compact count for hidden avatars and can render custom count text or act as a button.",
            "props": [
              {
                "name": "count",
                "type": "number",
                "description": "The number of hidden avatars. Used for the default `+N` label and the accessible label.",
                "required": true
              },
              {
                "name": "children",
                "type": "ReactNode",
                "description": "Optional custom count text rendered inside the indicator. Omit to use the default `+N` label."
              },
              {
                "name": "onClick",
                "type": "() => void",
                "description": "Callback fired when the overflow indicator is clicked. When provided, the indicator renders as a focusable button."
              },
              {
                "name": "ref",
                "type": "React.Ref<HTMLElement>",
                "description": "Ref forwarded to the overflow indicator element."
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "stylex.create() value — not an inline style object."
              }
            ],
            "playground": {
              "defaults": {
                "count": 2,
                "children": "+2"
              }
            },
            "usage": {
              "description": "AvatarGroupOverflow appears at the end of an AvatarGroup to summarize people who are not shown individually. Use it when a group is sliced to a small number of visible avatars but the hidden count still matters.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Pass the real hidden count to `count` so the accessible label matches the visible indicator."
                },
                {
                  "guidance": true,
                  "description": "Use short custom text such as `+12` or `99+`. The indicator is circular for short counts and grows into a pill for wider counts so the number always fits."
                },
                {
                  "guidance": true,
                  "description": "Provide `onClick` when the overflow opens a member list, popover, or detail view."
                },
                {
                  "guidance": false,
                  "description": "Do not pass custom text that disagrees with `count`; `count` continues to provide the accessible label."
                },
                {
                  "guidance": false,
                  "description": "Do not use long labels inside the indicator; place longer participant details next to the group instead."
                }
              ],
              "anatomy": [
                {
                  "name": "Count label",
                  "required": true,
                  "description": "The compact `+N` or custom count text displayed inside the circular indicator."
                },
                {
                  "name": "Button behavior",
                  "required": false,
                  "description": "When `onClick` is provided, the indicator becomes an interactive button with focus and hover states."
                }
              ]
            },
            "examples": [
              {
                "label": "Default overflow count",
                "code": "\n<AvatarGroup size=\"lg\">\n  {users.slice(0, 3).map(user => (\n    <Avatar key={user.id} src={user.src} name={user.name} />\n  ))}\n  <AvatarGroupOverflow count={users.length - 3} />\n</AvatarGroup>\n"
              },
              {
                "label": "Custom count text",
                "code": "\n<AvatarGroup size=\"lg\">\n  {users.slice(0, 3).map(user => (\n    <Avatar key={user.id} src={user.src} name={user.name} />\n  ))}\n  <AvatarGroupOverflow count={12}>12+</AvatarGroupOverflow>\n</AvatarGroup>\n"
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/AvatarGroup",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "AvatarStatusDot",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "AvatarStatusDot",
            "subComponentOf": "Avatar",
            "displayName": "Avatar Status Dot",
            "isHiddenFromOverview": true,
            "description": "Size-aware status indicator dot that reads avatar size from context and scales proportionally. Each variant pairs a colour with a distinct built-in shape (filled, ring, minus) so status is never conveyed by colour alone (WCAG 1.4.1).",
            "props": [
              {
                "name": "variant",
                "type": "'success' | 'neutral' | 'error'",
                "description": "Semantic variant pairing colour with a distinct shape: success = filled green dot, neutral = grey ring, error = red dot with a minus bar.",
                "default": "'success'"
              },
              {
                "name": "label",
                "type": "string",
                "description": "Accessible label describing the status. Inside an Avatar it is composed into the avatar's accessible name (e.g. \"Jane Doe, Online\"); the Avatar root is role=\"img\", which prunes child semantics, so the composed name is how the status reaches assistive tech. Standalone dots expose role=\"img\" with this label directly."
              },
              {
                "name": "icon",
                "type": "ReactNode",
                "description": "Icon centered inside the dot (hidden at tiny sizes). A rendered icon replaces the built-in shape glyph, so use a different icon per status.",
                "slotElements": [
                  {
                    "__element": "Icon",
                    "props": {
                      "icon": "check",
                      "size": "sm"
                    }
                  }
                ]
              }
            ],
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Avatar",
            "sourceAvailable": true
          }
        }
      }
    ]
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
